class Solution {
    private int answer=0;
    private int[] dfs(TreeNode node){
        if(node==null)return new int[]{
            -1,-1
        };
        int[] left=dfs(node.left),right=dfs(node.right);
        int goLeft=left[1]+1,goRight=right[0]+1;
        answer=Math.max(answer,Math.max(goLeft,goRight));
        return new int[]{
            goLeft,goRight
        };
    }
    public int longestZigZag(TreeNode root){
        dfs(root);
        return answer;
    }
}

code.kotlin:
class Solution {
    private var answer=0;
    private fun dfs(node:TreeNode?):IntArray{
        if(node==null)return intArrayOf(-1,-1);
        val left=dfs(node.left);
        val right=dfs(node.right);
        val goLeft=left[1]+1;
        val goRight=right[0]+1;
        answer=maxOf(answer,goLeft,goRight);
        return intArrayOf(goLeft,goRight)
    };
    fun longestZigZag(root:TreeNode?):Int{
        dfs(root);
        return answer
    }
}

